const body = $input.first().json.body || $input.first().json;
const record = body.record || body;

if (!record || !record.id) {
  throw new Error('Invalid webhook payload: missing feedback record.id');
}

const supabaseUrl = 'https://YOUR_PROJECT_ID.supabase.co';
const supabaseKey = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';

const rating = Number(record.rating) || 3;
const comment = (record.comment || '').trim();
const sentiment = record.sentiment || null;

return [{
  json: {
    id: record.id,
    guest_id: record.guest_id,
    booking_id: record.booking_id,
    rating,
    comment,
    sentiment,
    has_comment: comment.length > 0,
    supabase_url: supabaseUrl.replace(/\/$/, ''),
    supabase_key: supabaseKey
  }
}];

const rating = $json.rating;
let sentiment = 'neutral';

if (rating >= 4) {
  sentiment = 'positive';
} else if (rating <= 2) {
  sentiment = 'negative';
} else {
  sentiment = 'neutral';
}

return [{
  json: {
    id: $json.id,
    sentiment,
    supabase_url: $json.supabase_url,
    supabase_key: $json.supabase_key
  }
}];

const orig = $node["Validate Feedback Payload"].json;
const rating = Number(orig.rating) || 3;
const lower = (orig.comment || '').toLowerCase();

const fromRating = () => {
  if (rating >= 4) return 'positive';
  if (rating <= 2) return 'negative';
  const negative = ['bad', 'poor', 'dirty', 'rude', 'noisy', 'terrible', 'awful', 'disappointed', 'سيء', 'سيئ', 'قذر', 'مزعج', 'مستاء'];
  const positive = ['good', 'great', 'excellent', 'clean', 'friendly', 'comfortable', 'amazing', 'جيد', 'ممتاز', 'رائع', 'نظيف', 'مريح'];
  const neg = negative.some(w => lower.includes(w));
  const pos = positive.some(w => lower.includes(w));
  if (neg && !pos) return 'negative';
  if (pos && !neg) return 'positive';
  return 'neutral';
};

let rawText = '';
try {
  const inputData = $input.first().json;
  rawText = inputData.text || inputData.response || inputData.output || JSON.stringify(inputData);
} catch (e) {
  rawText = '';
}
rawText = String(rawText).replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : rawText);
} catch (err) {
  parsed = {};
}
if (!parsed || typeof parsed !== 'object') {
  parsed = {};
}

let sentiment = String(parsed.sentiment || '').toLowerCase().trim();
if (!['positive', 'neutral', 'negative'].includes(sentiment)) {
  sentiment = fromRating();
}

return [{
  json: {
    id: orig.id,
    sentiment,
    supabase_url: orig.supabase_url,
    supabase_key: orig.supabase_key
  }
}];
